import{_ as o,C as n,o as s,c as r,j as t,a as i,E as d,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Sensitive content handling","description":"","frontmatter":{},"headers":[],"relativePath":"security/sensitive-content.md","filePath":"security/sensitive-content.md"}'),c={name:"security/sensitive-content.md"};function h(u,e,p,f,g,m){const a=n("Badge");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"sensitive-content-handling",tabindex:"-1"},[i("Sensitive content handling "),t("a",{class:"header-anchor",href:"#sensitive-content-handling","aria-label":'Permalink to "Sensitive content handling"'},"​")],-1)),d(a,{type:"built",text:"Built"}),e[1]||(e[1]=l(' Octryx AI examines what goes to a model for sensitive content and acts on it per content kind. A Workspace admin chooses the action for each kind; a fresh install starts with the defaults below.<p>The kinds: credentials, credential assignments, email addresses, internal IP addresses, IBANs and phone numbers.</p><p>There are two places where this happens, and they work differently:</p><ul><li><strong>The platform&#39;s own model calls</strong>: the chat, tasks, governed runs and tool results. All five actions apply here.</li><li><strong>The gateway of external coding agents</strong>: the requests of Claude Code and Codex, on the governed route and on a seat. A request is forwarded unchanged or refused; nothing is masked or rerouted there.</li></ul><h2 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Defaults&quot;">​</a></h2><p>These apply on a fresh install, and in every Workspace that changes nothing.</p><table tabindex="0"><thead><tr><th>Where</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Platform&#39;s own model calls</strong></td><td>Credentials and email addresses are masked, internal IP addresses are reported, IBANs and phone numbers are not acted on</td></tr><tr><td><strong>Gateway of external coding agents</strong></td><td>Credentials are refused, credential assignments are reported (the request goes on, the finding is recorded); nothing else is acted on</td></tr><tr><td><strong>Command safety</strong></td><td>A command with credentials or internal IP addresses is sent for review</td></tr></tbody></table><h2 id="the-five-actions" tabindex="-1">The five actions <a class="header-anchor" href="#the-five-actions" aria-label="Permalink to &quot;The five actions&quot;">​</a></h2><p>A Workspace admin chooses one per kind in <strong>Agents › Governance › Policy</strong>, card <strong>Sensitive content handling</strong>. On the platform&#39;s own model calls:</p><table tabindex="0"><thead><tr><th>Action</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Refuse</strong> (<code>refuse</code>)</td><td>The request is not sent. The caller gets <code>content_policy_denied</code>.</td></tr><tr><td><strong>Mask</strong> (<code>mask</code>)</td><td>Each value is replaced by a numbered placeholder before the model sees it.</td></tr><tr><td><strong>Reroute</strong> (<code>reroute</code>)</td><td>The request goes to the Workspace&#39;s governance alias.</td></tr><tr><td><strong>Mask and reroute</strong> (<code>mask_reroute</code>)</td><td>Masked, and sent to the governance alias.</td></tr><tr><td><strong>Report only</strong> (<code>report</code>)</td><td>The text goes to the model unchanged; the finding is recorded as an informational decision.</td></tr></tbody></table><p>An admin can also set a kind back to its shipped default. Before you save, the card shows what the chosen action does at every place; on the gateway it shows &quot;platform calls only&quot; wherever the choice does not act there.</p><h3 id="the-governance-alias" tabindex="-1">The governance alias <a class="header-anchor" href="#the-governance-alias" aria-label="Permalink to &quot;The governance alias&quot;">​</a></h3><p>Each Workspace has one <strong>governance alias</strong>: the single governed model alias (an alias of an active model gateway) that every rerouting kind is sent to. Kinds carry no alias of their own.</p><ul><li>A kind can be set to reroute only while the Workspace has a governance alias (<code>content_handling_alias_required</code>).</li><li>The alias cannot be cleared while a kind still reroutes (<code>content_handling_alias_in_use</code>, naming the kinds); it can only be replaced by another governed alias.</li></ul><h3 id="where-reroute-does-not-apply" tabindex="-1">Where reroute does not apply <a class="header-anchor" href="#where-reroute-does-not-apply" aria-label="Permalink to &quot;Where reroute does not apply&quot;">​</a></h3><ul><li><strong>A model&#39;s reply</strong> goes back to the user, not to another model. There reroute and mask and reroute mask instead. The call&#39;s decision record is request-side: it says, for the request sent, which action was requested and which was applied. The reply adds no per-kind entries; a refused reply only sets <code>reply_refused: true</code> on that same record.</li><li><strong>A direct provider driver, and commands:</strong> reroute and mask and reroute are refused with <code>content_route_unavailable</code>.</li></ul><h2 id="on-the-gateway-of-external-coding-agents" tabindex="-1">On the gateway of external coding agents <a class="header-anchor" href="#on-the-gateway-of-external-coding-agents" aria-label="Permalink to &quot;On the gateway of external coding agents&quot;">​</a></h2><p>The gateway protects against <strong>accidental</strong> leakage by your own coding agent and against prompt injection arriving in tool results. It does not defend against a deliberately evasive client: Claude Code and Codex are your own programs and can reach any provider directly.</p><ul><li><strong>Forwarded unchanged or refused.</strong> The bytes sent are exactly the payload the gateway scanned.</li><li><strong>Only credentials and credential assignments act there.</strong> Credentials are refused by default, credential assignments reported by default; a Workspace can set <strong>Refuse</strong> or <strong>Report only</strong> for either. A credential assignment is a field whose name ends in a credential name (<code>password</code>, <code>db_password</code>, <code>access_token</code>, <code>client-secret</code>, …) with a literal value, also inside tool arguments, tool results and embedded JSON.</li><li><strong>Every other kind, and mask and the reroutes, apply to platform calls only.</strong> On the gateway such a setting leaves the kind at its default: a credential set to mask stays refused there.</li><li><strong>Prompt injection is checked only inside tool results</strong> (Claude Code&#39;s <code>tool_result</code> blocks, Codex&#39;s tool-call outputs). Found there, the request is refused (<code>content_policy_denied</code>). It is not checked in tool definitions, in your text, in the assistant&#39;s text or in the client&#39;s system prompt.</li><li><strong>The Workspace&#39;s custom content policies</strong> are asked too. A policy that blocks refuses the request; a policy that would mask or reroute also refuses it (<code>content_handling_gateway_refused</code>), because the gateway changes nothing. In shadow mode the request is sent and what the policy would have done is recorded.</li><li><strong>Bodies that cannot be checked are refused:</strong> invalid JSON (<code>request_body_invalid</code>), a body over 16 MiB (<code>request_body_too_large</code>), or a check not finished within 10 seconds (<code>content_scan_unfinished</code>). The next request is examined again.</li></ul><p>A refusal and a report notice name the decision record and say what to do next: remove the affected message or start a new conversation (Claude Code: <code>/rewind</code> or <code>/clear</code>; Codex: start a new session). A credential refusal names the kind of credential on the run&#39;s timeline.</p><h2 id="what-stays-fixed" tabindex="-1">What stays fixed <a class="header-anchor" href="#what-stays-fixed" aria-label="Permalink to &quot;What stays fixed&quot;">​</a></h2><p>No setting changes these:</p><ul><li>Text the detectors could not finish examining is withheld from a platform call; on the gateway the request is refused.</li><li>Content of an unknown shape in a platform call is refused (<code>content_unreadable</code>).</li><li>Prompt injection is refused: in every field a platform call sends to a model, and on the gateway in tool results.</li></ul><h2 id="who-can-change-it" tabindex="-1">Who can change it <a class="header-anchor" href="#who-can-change-it" aria-label="Permalink to &quot;Who can change it&quot;">​</a></h2><p>Workspace admins and owners, and platform admins. Members see the action in effect for each kind, and whether it is the default. Every change of an action or of the governance alias is written to the audit log as <code>content_handling.changed</code>; see <a href="/docs/admin/governance">Governance</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><p>See <a href="/docs/start/known-limitations#sensitive-content-handling">Known limitations</a>.</p><h2 id="reference-how-the-checks-work" tabindex="-1">Reference: how the checks work <a class="header-anchor" href="#reference-how-the-checks-work" aria-label="Permalink to &quot;Reference: how the checks work&quot;">​</a></h2><p>The exact behaviour, for admins and reviewers who need it.</p><h3 id="the-gateway-in-detail" tabindex="-1">The gateway in detail <a class="header-anchor" href="#the-gateway-in-detail" aria-label="Permalink to &quot;The gateway in detail&quot;">​</a></h3><p>The gateway covers the Anthropic route and the Claude Code seat, and the <code>/openai</code> Responses route and the Codex seat. A governed call&#39;s final payload is built before the scan: the model replaced by the alias&#39; model group and, on the Responses route, the effective output cap. A seat call sends the client&#39;s body as it arrived. The bytes sent are exactly the serialization of the payload the gateway scanned; there is no separate final check on the gateway.</p><p>The threat model has three consequences: no protocol-shape validation beyond JSON parsing; opaque fields skipped by an exact key list without content validation (below); caller-supplied names and types are not verified.</p><ul><li><strong>What is scanned.</strong> The whole JSON payload as one text, minus the values under the opaque key list, plus the structured credential assignments of its parsed keys and values. A field whose name ends in a credential name assigning a literal value is a <code>credential_assignment</code> finding: in tool arguments, tool results and prompt data, a string that is itself serialized JSON included, the opaque list honoured. It is classified the same way for refuse and report.</li><li><strong>Prompt injection</strong> is checked only inside tool results: Anthropic <code>tool_result</code> blocks, Responses <code>function_call_output</code> and <code>*_call_output</code> items, each read as one text. It is not checked in tool definitions, in the user&#39;s, the assistant&#39;s or the client&#39;s system text, in citations or in search items.</li><li><strong>Bodies that cannot be checked.</strong> Not valid JSON (a repeated key, a nesting deeper than 64, a non-finite number such as a <code>NaN</code> or <code>Infinity</code> literal or a number beyond the float range, invalid UTF-8): <code>request_body_invalid</code> (400). Over 16 MiB: <code>request_body_too_large</code> (413). Not checked before the deadline: <code>content_scan_unfinished</code> (400). Nothing unfinished is remembered: the next request is examined again.</li><li><strong>Deadline.</strong> 10 seconds from the moment the request handler is entered, the body read included. It bounds the content examination, from entry to the last scan, the structured fields and the bytes to send. The clock is read once after all of it; a passed deadline is the fixed unfinished refusal, before any finding reaches a custom policy or a record. Admission, budget and commit steps after a finished examination are not content work and are not bounded by it.</li><li><strong>Custom content policies</strong> (Cedar) are asked over the whole body&#39;s findings. A blocking policy refuses with <code>content_policy_denied</code>; an obligation to mask or reroute refuses with <code>content_handling_gateway_refused</code>; in shadow mode the request is sent and what the policy would have done is recorded.</li></ul><h4 id="decision-records-on-the-gateway" tabindex="-1">Decision records on the gateway <a class="header-anchor" href="#decision-records-on-the-gateway" aria-label="Permalink to &quot;Decision records on the gateway&quot;">​</a></h4><p>A content decision record is written once, when the request ends, from its actual final outcome:</p><ul><li>for every request refused for a content reason: an unreadable, oversized or late body, a fixed rule, the content handling, a tool-result policy, or a custom policy. It is <code>refused</code>, with the reason and the stage (<code>body</code>, <code>content</code>, <code>tool_result_policy</code>, <code>cedar</code>);</li><li>for every request with acted-on or reported findings.</li></ul><p>It never claims an action that was not applied:</p><ul><li>A request with findings that was sent is <code>forwarded</code> (<code>applied: report</code>), also when the upstream answered with an error status (<code>upstream_status</code>): the body crossed the transport, so it is never <code>refused</code>. A request counts as sent the moment the upstream&#39;s response headers arrive, before any error body is read.</li><li>A request with findings that was not sent for another reason (a budget, an undelivered send, a cancellation or failure) is <code>not_sent</code>, with that reason and stage (<code>applied: none</code>).</li><li>A tool-result injection refusal states the injection&#39;s count and source (<code>prompt_injection</code>).</li><li>A refusal for a non-content reason with nothing found (run limits, admission, budget or cost, authentication, a model denial, loop protection), and a clean forward, write no content record.</li></ul><p>The refusal and the report notice (header <code>x-octryx-obligation</code>, on every returned answer, upstream errors and token counts included) name the record and say what to do next. A credential refusal names the kind of credential on the run&#39;s timeline. The Agents badge counts what the newest turn carries.</p><h3 id="the-opaque-key-list" tabindex="-1">The opaque key list <a class="header-anchor" href="#the-opaque-key-list" aria-label="Permalink to &quot;The opaque key list&quot;">​</a></h3><p>The only values not read, by key, wherever they are, without validating their content. The same list applies on the gateway and on the platform&#39;s own calls.</p><table tabindex="0"><thead><tr><th>Key</th><th>Skipped when</th></tr></thead><tbody><tr><td><code>signature</code></td><td>its value is a string (a thinking block&#39;s signed state)</td></tr><tr><td><code>encrypted_content</code></td><td>its value is a string (encrypted reasoning, compaction or web-search state)</td></tr><tr><td><code>data</code></td><td>its value is a string in an object whose <code>type</code> is <code>base64</code> (a media source) or <code>redacted_thinking</code></td></tr><tr><td><code>image_url</code>, <code>url</code>, <code>file_data</code></td><td>its value is a <code>data:</code> URL (an inline image or file)</td></tr></tbody></table><h3 id="the-platform-s-own-model-calls-in-detail" tabindex="-1">The platform&#39;s own model calls in detail <a class="header-anchor" href="#the-platform-s-own-model-calls-in-detail" aria-label="Permalink to &quot;The platform&#39;s own model calls in detail&quot;">​</a></h3><ul><li><strong>One budget per call.</strong> Every provider-bound field is examined once within one budget for the whole call: size, number of parts, and a deadline from the call&#39;s entry to the last scan, the final check&#39;s serialization included. The size cap counts the full serialized bytes, opaque values included. The clock is read once more after all content work; a deadline passed during the examination is the fixed unfinished refusal. The custom policies&#39; scans of a governed call, an obligation&#39;s masking pass included, are charged to the same budget. Once it is spent, the call is refused unfinished (<code>content_scan_unfinished</code>, a notice without counts) before any later decision.</li><li><strong>Refuse and history.</strong> A kind set to refuse refuses new content (the newest turn, system text, message fields) and newly offered tool definitions. Found in older history or in a replayed tool call, it is masked instead: that text was checked when it was new.</li><li><strong>Prompt injection</strong> is refused in every field sent to the model, the newest user text included. An administrator-authored agent role (&quot;Act as …&quot;) is the one phrasing not refused there.</li><li><strong>Platform instructions.</strong> A platform instruction is sent unchecked only when its text is exactly a shipped seed text (by content hash). An edited or Workspace-authored instruction is checked like any authored text.</li><li><strong>Unreadable structure.</strong> A request whose structure cannot be read (messages that are not a list of objects, a nesting deeper than 64, text that is not valid Unicode, a role that is not a string, an unknown block) is refused with <code>content_unreadable</code> before anything copies or hashes it.</li></ul><h4 id="the-final-check" tabindex="-1">The final check <a class="header-anchor" href="#the-final-check" aria-label="Permalink to &quot;The final check&quot;">​</a></h4><p>Right before a provider driver sends, the final request object it hands to its transport or SDK is read once more as one JSON text, minus the opaque key list, with the same structured credential classification as the gateway. It never rewrites text. The only text not read is a field that is exactly a shipped seed text.</p><p>Prompt injection is not evaluated in a system carrier of the driver&#39;s request whose value is exactly an authored system text of the call, or exactly the driver&#39;s join of the call&#39;s system texts. A system carrier is the top-level <code>system</code> or <code>systemInstruction</code>, or a message of the top-level <code>messages</code> or <code>input</code> list whose <code>role</code> is <code>system</code> or <code>developer</code>. Nothing else is looked at for a role: the same text in any other field, or inside a longer value, is evaluated, and every other detector reads the authored field whole.</p><p>The call is refused and nothing is sent if:</p><ul><li>prompt injection, or a kind whose action must keep it out (refuse, mask, mask and reroute), is still there;</li><li>a rerouting kind is there while the call is not going to the Workspace&#39;s governance alias;</li><li>the call ran out of its budget.</li></ul><p>Right before the send, after the custom policies, a call that a rerouting kind sent to the governance alias must still be going there; a mismatch is refused with <code>content_route_unavailable</code>.</p><h4 id="the-record-of-a-platform-call" tabindex="-1">The record of a platform call <a class="header-anchor" href="#the-record-of-a-platform-call" aria-label="Permalink to &quot;The record of a platform call&quot;">​</a></h4><p>The record is request-side only. It is written once, after the request was handed to the transport, from the final check&#39;s reading of the sent bytes:</p><ul><li>a kind present in them is recorded with its applied action, <code>report</code> or <code>reroute</code>;</li><li>a kind the examination of the input found and the sent bytes do not carry is recorded <code>mask</code>;</li><li>a report first seen in the sent bytes is included; a report this process already recorded for the same text is named <code>reported_before</code>, and the earlier record keeps counting it;</li><li>a refused call is recorded <code>refuse</code>, refusals by custom policies and by the final check included;</li><li>a call neither refused nor sent (the driver failed, or the call was cancelled before the hand-off) has no record.</li></ul><p>The reply is masked or refused as configured but leaves no per-kind evidence: a refused reply only sets <code>reply_refused: true</code> on the call&#39;s record, and a reply part whose examination does not finish is withheld. The conversation&#39;s badge is counted after the record.</p><h3 id="tool-results" tabindex="-1">Tool results <a class="header-anchor" href="#tool-results" aria-label="Permalink to &quot;Tool results&quot;">​</a></h3><p>Each released tool result has at most one decision record, written once from what was actually released: unchanged, masked, blocked, or kept by a coding agent&#39;s client that cannot take a masked output. A result released unchanged with nothing to state has none.</p><ul><li>Each kind&#39;s <code>applied</code> is read from the released result: <code>report</code> only for a reported kind it carries; <code>mask</code> only for a kind found and absent from it (a Workspace policy&#39;s mask); otherwise <code>none</code>, because it applies where the result next reaches a model. <code>informational</code> lists the kinds applied as <code>report</code>.</li><li>A blocked result is <code>refuse</code>; an unfinished examination is the fixed record without findings.</li><li>The record is written when the check returns the result to its caller; a check that fails or is cancelled before that writes nothing.</li><li>A result the client keeps (a built-in tool) is released as it came, with nothing claimed as blocked, masked or withheld; the launcher&#39;s notice says the output stays and the gateway checks it. A Workspace policy&#39;s part, and a withheld count, are stated only for a released result.</li></ul><p>The conversation&#39;s badge counts only what entered the context, after the record.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/security/redaction">Secret redaction</a>: secrets replaced with <code>[redacted]</code> before text is stored, shown or sent on.</li><li><a href="/docs/rules/policies">Policies and four-eyes</a>: policies, detectors and the <strong>Content security</strong> overview.</li><li><a href="/docs/security/data-classes">Data classes</a>: which models may see a Workspace&#39;s data at all.</li></ul>',60))])}const b=o(c,[["render",h]]);export{w as __pageData,b as default};
